// chips 组：视觉高亮切换（无图表）
let activeChip = '全市'

// 各 tab 组内可识别的按钮文案（current 态来自设计稿原样 DOM，需按文案补 data-tab）
const TAB_LABELS = ['历史累计', '当月新增', '当月数量', '本年数据', '当月数据', '图表趋势']

// 数智页统计指标（苏住房 G 端首页统计接口，参照 zhi2-web-admin src/api/portal/home.js）。
// 仅「物业管理标准化评价」后端暂无接口，保持设计稿静态展示。
const d = reactive<{ key?: KeyData; benefit?: BenefitData; repair?: RepairData; sunshine?: SunshineOverview }>({})

// 行政区划 chips：默认含苏州全市区县（接口兜底），接口返回后按后端 region/list 顺序覆盖。
// 顺序与 G 端一致，横向滚动保证最后一个区（高新区/虎丘区）完整显示（修复 bug 6456）。
const SUZHOU_DISTRICTS_FALLBACK = [
  '张家港市',
  '常熟市',
  '太仓市',
  '昆山市',
  '吴江区',
  '吴中区',
  '相城区',
  '姑苏区',
  '苏州工业园区',
  '虎丘区',
]
const regionNames = ref<string[]>(SUZHOU_DISTRICTS_FALLBACK)

// 仅回填语义唯一、映射明确的头条指标；明细子网格、图表与「物业管理标准化评价」保持设计稿。
function num(v: unknown): number {
  if (typeof v === 'number') return v
  if (v == null) return NaN
  return Number(String(v).replace(/[, ]/g, ''))
}
function fmtVal(v: string | number): string {
  if (typeof v === 'number') {
    if (Number.isNaN(v)) return ''
    return Number.isInteger(v)
      ? v.toLocaleString('en-US')
      : v.toLocaleString('en-US', { maximumFractionDigits: 2 })
  }
  return String(v)
}
function statValue(label: string): string | number | undefined {
  const k = d.key
  const b = d.benefit
  const r = d.repair
  const s = d.sunshine
  switch (label) {
    case '物业管理区域数量（个）':
      return k ? num(k.complexNum) : undefined
    case '物业管理区域建筑面积（万㎡）':
      return k ? num(k.floorAreaTotal) / 10000 : undefined
    case '物业服务企业数量（个）':
      return k ? num(k.companyNum) : undefined
    case '开户主体数（个）':
      return b ? num(b.monthOrgNum) : undefined
    case '监管账户数（个）':
      return b ? num(b.monthAccountNum) : undefined
    case '已签协议专户数（个）':
      return b ? num(b.monthAgreementNum) : undefined
    case '公共收益资金总额（万元）':
      return b ? num(b.fundAmount) : undefined
    case '本月新增工单数(件)':
      return r ? num(r.monthAddNum) : undefined
    case '本月已完成工单数(件)':
      return r ? num(r.monthCompletedNum) : undefined
    case '本月未完成工单数(件)':
      return r ? num(r.monthUncompletedNum) : undefined
    case '满意度占比':
      return r ? num(r.satisfactionRate) : undefined
    case '物业服务(条)':
      return s ? num(s.propertyServiceCount) : undefined
    case '公共收益(条)':
      return s ? num(s.publicBenefitCount) : undefined
    case '维修资金(条)':
      return s ? num(s.maintenanceFundCount) : undefined
    default:
      return undefined
  }
}
/** 把统计接口数据按「标签文案」回填到设计稿静态 DOM（标签→相邻数值节点）。 */
function bindStats() {
  const host = hostEl()
  if (!host) return
  host.querySelectorAll('.text-on-surface-variant').forEach((labelEl) => {
    const label = (labelEl.textContent || '').trim()
    const val = statValue(label)
    if (val === undefined || (typeof val === 'number' && Number.isNaN(val))) return
    // 定位数值节点：向上至多 4 层祖先，取其直接子节点中含 .font-bold 的那个
    let el: HTMLElement | null = labelEl as HTMLElement
    let valEl: HTMLElement | null = null
    for (let i = 0; i < 4 && el; i++) {
      const cand = Array.from(el.children).find(
        (c) => c instanceof HTMLElement && c.classList.contains('font-bold'),
      ) as HTMLElement | undefined
      if (cand) {
        valEl = cand
        break
      }
      el = el.parentElement
    }
    if (valEl) valEl.textContent = fmtVal(val)
  })
}

